INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES
('education', 'jee/physics', 'units-dimensions', 'The dimensional formula of force is:', '["[MLT^-2]", "[MLT^-1]", "[ML^2T^-2]", "[ML^-1T^-2]"]', 0, 'Force = mass x acceleration = M x (LT^-2) = [MLT^-2].', 'beginner'),
('education', 'jee/physics', 'units-dimensions', 'The dimensional formula of energy (or work) is:', '["[ML^2T^-2]", "[MLT^-2]", "[ML^2T^-1]", "[MLT^-1]"]', 0, 'Energy/work = force x distance = [MLT^-2] x [L] = [ML^2T^-2].', 'intermediate'),
('education', 'jee/physics', 'units-dimensions', 'Dimensional analysis is primarily used to check the ___ of a physical equation.', '["Consistency (homogeneity of dimensions)", "Numerical accuracy", "Sign convention", "Vector direction"]', 0, 'Dimensional analysis verifies that both sides of an equation have matching dimensions, a necessary (though not sufficient) condition for the equation to be physically valid.', 'beginner'),
('education', 'jee/physics', 'units-dimensions', 'The number of significant figures in the measurement 0.00420 is:', '["3", "6", "2", "5"]', 0, 'Leading zeros are not significant; the digits 4, 2, and the trailing 0 (after the decimal, following non-zero digits) are significant, giving 3 significant figures.', 'intermediate'),
('education', 'jee/physics', 'units-dimensions', 'The SI unit of pressure is the:', '["Pascal", "Newton", "Joule", "Watt"]', 0, 'Pressure (force per unit area) has the SI unit Pascal (Pa), equivalent to N/m^2.', 'beginner'),
('education', 'jee/physics', 'kinematics', 'The equation v = u + at relates final velocity v to initial velocity u, acceleration a, and:', '["Time t", "Displacement s", "Mass m", "Force F"]', 0, 'This is the first equation of motion under constant acceleration, relating velocity change to time elapsed.', 'beginner'),
('education', 'jee/physics', 'kinematics', 'A ball is thrown vertically upward with initial velocity 20 m/s (g = 10 m/s^2). The maximum height reached is:', '["20 m", "10 m", "40 m", "5 m"]', 0, 'At maximum height, v=0. Using v^2 = u^2 - 2gh: 0 = 400 - 2(10)h, so h = 400/20 = 20 m.', 'intermediate'),
('education', 'jee/physics', 'kinematics', 'For a projectile launched at angle theta with speed u, the time of flight (on level ground) is given by:', '["2u sin(theta) / g", "u sin(theta) / g", "u cos(theta) / g", "2u cos(theta) / g"]', 0, 'The time of flight for a projectile on level ground is T = 2u sin(theta) / g, derived from the vertical motion component.', 'intermediate'),
('education', 'jee/physics', 'kinematics', 'In uniform circular motion, the direction of the centripetal acceleration is:', '["Toward the center of the circle", "Tangential to the circle", "Away from the center", "Along the axis of rotation"]', 0, 'Centripetal acceleration always points toward the center of the circular path, which is what keeps the object moving in a circle rather than a straight line.', 'beginner'),
('education', 'jee/physics', 'kinematics', 'Relative velocity of object A with respect to object B is given by:', '["v(A) - v(B)", "v(A) + v(B)", "v(B) - v(A)", "v(A) x v(B)"]', 0, 'Relative velocity of A with respect to B is the vector difference v(A/B) = v(A) - v(B).', 'beginner'),
('education', 'jee/physics', 'laws-of-motion', 'Newton''s Second Law of Motion states that the net force on an object equals:', '["Mass times acceleration (F = ma)", "Mass divided by acceleration", "Mass times velocity", "Mass times displacement"]', 0, 'Newton''s Second Law: the net force acting on an object is directly proportional to its mass and acceleration, F = ma.', 'beginner'),
('education', 'jee/physics', 'laws-of-motion', 'The coefficient of static friction is generally ___ the coefficient of kinetic friction for the same surfaces.', '["Greater than or equal to", "Less than", "Exactly equal to, always", "Unrelated to"]', 0, 'Static friction is generally slightly greater than or equal to kinetic friction, since more force is needed to start motion than to sustain it.', 'intermediate'),
('education', 'jee/physics', 'laws-of-motion', 'A pseudo (fictitious) force arises when analyzing motion from the perspective of:', '["A non-inertial (accelerating) reference frame", "An inertial reference frame only", "A stationary observer only", "Any frame, inertial or not"]', 0, 'Pseudo forces are introduced only in non-inertial (accelerating) reference frames, to make Newton''s laws appear to hold within that frame.', 'intermediate'),
('education', 'jee/physics', 'laws-of-motion', 'A block of mass 2 kg experiences a net force of 10 N. Its acceleration is:', '["5 m/s^2", "20 m/s^2", "0.2 m/s^2", "12 m/s^2"]', 0, 'By F=ma, a = F/m = 10/2 = 5 m/s^2.', 'intermediate'),
('education', 'jee/physics', 'laws-of-motion', 'Newton''s Third Law states that for every action, there is:', '["An equal and opposite reaction", "A proportionally larger reaction", "No corresponding reaction", "A reaction only in fluids"]', 0, 'Newton''s Third Law: forces always occur in pairs -- for every action force, there is an equal and opposite reaction force acting on a different object.', 'beginner'),
('education', 'jee/physics', 'work-energy', 'The Work-Energy Theorem states that the work done by the net force on an object equals its:', '["Change in kinetic energy", "Change in potential energy", "Change in momentum", "Total mechanical energy"]', 0, 'The Work-Energy Theorem: net work done on an object equals the change in its kinetic energy, W = deltaKE.', 'beginner'),
('education', 'jee/physics', 'work-energy', 'In an elastic collision between two bodies, which quantities are conserved?', '["Both momentum and kinetic energy", "Only momentum", "Only kinetic energy", "Neither momentum nor kinetic energy"]', 0, 'An elastic collision is defined by the conservation of both total momentum and total kinetic energy of the system.', 'beginner'),
('education', 'jee/physics', 'work-energy', 'The SI unit of power is the:', '["Watt", "Joule", "Newton", "Pascal"]', 0, 'Power, the rate of doing work, has the SI unit Watt (1 Watt = 1 Joule per second).', 'beginner'),
('education', 'jee/physics', 'work-energy', 'A force of 5 N acts on an object, moving it 4 m in the direction of the force. The work done is:', '["20 J", "9 J", "1.25 J", "20 N"]', 0, 'Work = force x displacement (in the direction of force) = 5 N x 4 m = 20 J.', 'intermediate'),
('education', 'jee/physics', 'work-energy', 'The gravitational potential energy of an object of mass m at height h above the ground is given by:', '["mgh", "mgh^2", "(1/2)mgh", "mg/h"]', 0, 'Gravitational potential energy near Earth''s surface is PE = mgh, where g is the acceleration due to gravity.', 'beginner'),
('education', 'jee/physics', 'rotation', 'Torque is defined as the cross product of the position vector r and the force vector F, given by:', '["r x F", "r . F", "r + F", "r / F"]', 0, 'Torque (moment of force) is the vector (cross) product tau = r x F, with magnitude rF sin(theta).', 'beginner'),
('education', 'jee/physics', 'rotation', 'The moment of inertia of a solid sphere about its diameter is given by:', '["(2/5) M R^2", "(1/2) M R^2", "M R^2", "(2/3) M R^2"]', 0, 'The standard moment of inertia formula for a uniform solid sphere about an axis through its center (diameter) is (2/5)MR^2.', 'intermediate'),
('education', 'jee/physics', 'rotation', 'Angular momentum L of a rotating body is given by the product of:', '["Moment of inertia and angular velocity (L = I omega)", "Mass and linear velocity", "Torque and time", "Moment of inertia and angular acceleration"]', 0, 'Angular momentum is the rotational analog of linear momentum: L = I x omega, where I is moment of inertia and omega is angular velocity.', 'beginner'),
('education', 'jee/physics', 'rotation', 'For pure rolling motion of a wheel without slipping, the relationship between linear velocity v and angular velocity omega is:', '["v = R omega", "v = R / omega", "v = omega / R", "v = R + omega"]', 0, 'In pure rolling without slipping, the contact point has zero velocity, giving the condition v = R omega, where R is the wheel''s radius.', 'intermediate'),
('education', 'jee/physics', 'rotation', 'The Parallel Axis Theorem relates the moment of inertia about any axis to the moment of inertia about a parallel axis through the:', '["Center of mass", "Point of application of force", "Axis of symmetry only", "Edge of the object"]', 0, 'The Parallel Axis Theorem: I = I(cm) + Md^2, where I(cm) is the moment of inertia about a parallel axis through the center of mass, and d is the distance between the two axes.', 'intermediate')
